<script setup>
import {computed,ref,onMounted,watch} from 'vue'
import MathText from '../../../core/math/components/MathText.vue'
const props=defineProps({lesson:{type:String,required:true}}),slides=ref([]),index=ref(0),error=ref('')
const decks=import.meta.glob('../../../content/courses/bieu-dien-tri-thuc/lectures/*/slides.mjs')
async function load(){try{const read=decks['../../../content/courses/bieu-dien-tri-thuc/lectures/'+props.lesson+'/slides.mjs'];if(!read)throw Error('Unknown lesson');const module=await read();slides.value=module.slides;index.value=0;error.value=''}catch{error.value='Chưa tải được thẻ ôn tập. Hãy mở lại trang khi có kết nối.'}}
onMounted(load);watch(()=>props.lesson,load)
const slide=computed(()=>slides.value[index.value])
</script>
<template><section class="knowledge-review" aria-label="Thẻ ôn tập nhanh"><p v-if="error" role="alert">{{ error }}</p><template v-else-if="slide"><div class="review-controls"><button type="button" :disabled="index===0" aria-label="Thẻ ôn tập trước" @click="index--">← Trước</button><label>Thẻ ôn tập<select v-model.number="index"><option v-for="(s,i) in slides" :key="i" :value="i">{{ i+1 }}. {{ s.title }}</option></select></label><button type="button" :disabled="index===slides.length-1" aria-label="Thẻ ôn tập tiếp" @click="index++">Tiếp →</button></div><article class="review-card" aria-live="polite"><p class="review-counter">{{ index+1 }} / {{ slides.length }}</p><h3>{{ slide.title }}</h3><ul><li v-for="(bullet,i) in slide.bullets" :key="i"><MathText :text="bullet"/></li></ul><MathText v-if="slide.formula" as="div" :text="slide.formula"/><MathText v-if="slide.example" as="p" :text="slide.example"/></article></template><p v-else role="status">Đang tải thẻ ôn tập…</p></section></template>
<style scoped>
.knowledge-review{min-width:0;margin:24px 0}.review-controls{display:flex;align-items:end;gap:8px;flex-wrap:wrap}.review-controls label{flex:1 1 170px;min-width:0;display:grid;gap:6px;font:var(--fs-small)/1.6 var(--font-ui)}.review-controls :is(button,select){min-height:44px;max-width:100%;min-width:0;padding:8px;border:1px solid var(--control);border-radius:var(--radius);background:var(--paper);color:var(--ink);font:inherit}.review-controls button{cursor:pointer}.review-controls button:disabled{opacity:.5;cursor:default}.review-card{margin-top:16px;border:1px solid var(--rule);border-radius:var(--radius);background:var(--paper);padding:20px;min-width:0}.review-card h3{margin:8px 0 16px;font:600 var(--fs-h3)/1.5 var(--font-ui);overflow-wrap:anywhere}.review-card ul{padding-left:20px;font:var(--fs-ui)/1.8 var(--font-ui)}.review-card li{margin:12px 0}.review-counter{color:var(--ink-2);font:var(--fs-small) var(--font-ui);margin:0}:is(button,select):focus-visible{outline:3px solid var(--tim);outline-offset:3px}@media(max-width:480px){.review-card{padding:12px}.review-controls label{order:-1;flex-basis:100%}}
</style>
